var score: int = 0
var high_score: int = 0
var current_topic_title: String = ""
var topic_records: Dictionary = {}


func _ready() -> void:
	load_high_score()
	load_topic_records()


func save_high_score() -> void:
	var save_data: Dictionary = {
		"high_score": high_score
	}
	var json_string: String = JSON.stringify(save_data)
	var file: FileAccess = FileAccess.open("user://savegame.json", FileAccess.WRITE)
	if file != null:
		file.store_string(json_string)


func load_high_score() -> void:
	if not FileAccess.file_exists("user://savegame.json"):
		high_score = 0
		return

	var file: FileAccess = FileAccess.open("user://savegame.json", FileAccess.READ)
	if file == null:
		high_score = 0
		return

	var content: String = file.get_as_text()
	var json: JSON = JSON.new()
	var parse_result: Error = json.parse(content)

	if parse_result != OK:
		high_score = 0
		return

	if json.data is Dictionary and json.data.has("high_score"):
		high_score = int(json.data["high_score"])
	else:
		high_score = 0


func save_topic_records() -> void:
	var json_string: String = JSON.stringify(topic_records)
	var file: FileAccess = FileAccess.open("user://records.json", FileAccess.WRITE)
	if file != null:
		file.store_string(json_string)


func load_topic_records() -> void:
	if not FileAccess.file_exists("user://records.json"):
		topic_records = {}
		return

	var file: FileAccess = FileAccess.open("user://records.json", FileAccess.READ)
	if file == null:
		topic_records = {}
		return

	var content: String = file.get_as_text()
	var json: JSON = JSON.new()
	var parse_result: Error = json.parse(content)

	if parse_result != OK:
		topic_records = {}
		return

	if json.data is Dictionary:
		topic_records = json.data
	else:
		topic_records = {}
